<script setup lang="ts">
import { product } from '../brand'
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { api } from '../api'
import { businessCell, businessLabel, categoryLabel } from '../businessFormat'
import type { BusinessExample, BusinessExampleDetail } from '../exampleTypes'
import MarkdownReport from './MarkdownReport.vue'

defineProps<{busy?:boolean}>()
const emit=defineEmits<{start:[example:BusinessExample,question?:string]}>()
const cases=ref<BusinessExample[]>([]),detail=ref<BusinessExampleDetail|null>(null)
const loading=ref(false),error=ref(''),selectedId=ref(''),section=ref('journey'),step=ref('overview')
const titleElement=ref<HTMLElement|null>(null)
let version=0
const labels:Record<string,string>={overview:'看经营变化',sales_drivers:'拆解单均金额',sales_categories:'定位品类',delivery_states:'排查配送'}
const statusLabels:Record<string,string>={delivered:'已送达',shipped:'已发货',canceled:'已取消',unavailable:'不可用',invoiced:'已开票',processing:'处理中',approved:'已批准',created:'已创建'}
const sections=[['journey','任务与进展'],['results','分析结果'],['followups','待核查事项'],['confirmation','交付前确认'],['sources','数据来源']]
const result=computed(()=>detail.value?.results.find(r=>r.step===step.value))
const overview=computed(()=>detail.value?.results.find(r=>r.step==='overview')?.rows || [])
const before=computed(()=>overview.value[0]),after=computed(()=>overview.value[1])
const reportOpen=ref(false)
const shownRows=computed(()=>result.value?.rows.slice(0,showAll.value?200:5)||[])
const showAll=ref(false)
function scopeLabel(example:BusinessExample){const f=example.filters;return [f.states?.join('、')||'全部地区',f.order_statuses?.length?f.order_statuses.map(s=>statusLabels[s]||s).join('、')+'订单':'全部订单状态',f.categories?.map(categoryLabel).join('、')||'全部品类'].join(' · ')}
async function loadCatalog(){loading.value=true;error.value='';const current=++version;try{const value=await api.reviewExamples();if(current===version)cases.value=value}catch(e){if(current===version)error.value=String(e)}finally{if(current===version)loading.value=false}}
async function open(id:string){selectedId.value=id;detail.value=null;error.value='';loading.value=true;reportOpen.value=false;const current=++version;try{const value=await api.reviewExample(id);if(current!==version)return;detail.value=value;section.value='journey';step.value=value.focus;showAll.value=false;await nextTick();titleElement.value?.focus()}catch(e){if(current===version)error.value=String(e)}finally{if(current===version)loading.value=false}}
function back(){const previous=selectedId.value;version++;detail.value=null;selectedId.value='';loading.value=false;error.value='';nextTick(()=>document.getElementById('example-card-'+previous)?.focus())}
function viewResult(value:string){step.value=value;section.value='results';showAll.value=false;reportOpen.value=false}
function download(){if(!detail.value)return;const d=detail.value;const notes=d.followups.map(t=>'- 待核查：'+t.title+'。'+t.reason).join('\n');const evidence=d.report.fact_references.map(f=>`- ${f.label}：${f.display}；来源：${f.source_title}；范围：${f.scope}`).join('\n');const text=`# ${d.report.title}\n\n${d.objective}\n\n${d.summary}\n\n${d.report.markdown}\n\n## 待核查事项\n\n${notes}\n\n## 交付前确认\n\n汇总已按当前样本核对；原因判断与业务建议待人工确认，未记录真实审批。\n\n## 数据来源\n\n${d.source.name} · ${d.source.url} · ${d.source.license}\n${d.source.note}\n\n## 数值依据\n\n${evidence}`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${product.name}-${d.id}-示例复盘.md`;a.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(loadCatalog)
onUnmounted(()=>{version++})
</script>

<template>
<section class="business-examples" aria-label="业务场景示例">
  <template v-if="!selectedId">
    <header class="examples-heading"><span class="eyebrow">跟着真实数据，走完一次业务任务</span><h1>先看一个完整的分析案例</h1><p>从业务问题到分析结果，再到待核查事项与交付确认。三个场景均使用 Olist 公开历史订单，浏览后可按同样范围开始自己的分析。</p></header>
    <div class="example-cards"><article v-for="(example,index) in cases" :key="example.id"><span class="case-number">0{{index+1}} / {{example.tag}}</span><h2>{{example.title}}</h2><p>{{example.description}}</p><dl><dt>适合谁</dt><dd>{{example.persona}}</dd><dt>数据范围</dt><dd>{{example.month}} · {{scopeLabel(example)}}</dd></dl><button type="button" :id="'example-card-'+example.id" :aria-label="'浏览案例：'+example.title" @click="open(example.id)">浏览完整案例 <span aria-hidden="true">→</span></button></article></div>
    <p class="case-note">数值来自真实公开历史样本；角色、任务和待核查事项为示例编排。你可以直接浏览任意场景。</p>
  </template>
  <template v-else><button type="button" class="back-link" @click="back">← 返回场景目录</button></template>
  <div v-if="loading" class="example-state" role="status">{{selectedId?'正在按统一口径计算案例的四步结果…':'正在加载场景目录…'}}</div>
  <div v-if="error" class="example-state failure" role="alert">{{error}} <button type="button" @click="selectedId?open(selectedId):loadCatalog()">重新加载</button></div>
  <template v-if="detail">
    <header class="detail-heading"><span class="eyebrow">{{detail.tag}} · 完整示例</span><h1 ref="titleElement" tabindex="-1">{{detail.title}}</h1><p>{{detail.objective}}</p><p class="scope-line">{{detail.month}} 对比 {{detail.previous_month}} · {{scopeLabel(detail)}} · 下单时间 · BRL</p><div class="example-actions"><button type="button" class="primary" :disabled="busy" @click="emit('start',detail)">按此场景开始我的分析</button><button type="button" @click="download">下载示例报告</button></div><p class="case-note">浏览不产生你的分析记录；开始分析后会重新计算并独立保存，月份和范围可在后续调整。</p></header>
    <nav class="example-sections" aria-label="示例内容"><button v-for="[key,label] in sections" :key="key" type="button" :aria-pressed="section===key" @click="section=key">{{label}}</button></nav>
    <section v-if="section==='journey'" class="case-panel" aria-label="示例任务与进展">
      <div class="section-intro"><h2>这次任务要完成什么</h2><p>{{detail.persona}}需要{{detail.objective}}</p><span class="status-tag">示例分析已完成 · 待人工核查与确认</span></div>
      <div v-if="before && after" class="case-metrics"><div v-for="field in ['orders','item_sales','late_rate']" :key="field"><small>{{businessLabel(field)}}</small><strong>{{businessCell(after[field],field,'BRL')}}</strong><span>上月 {{businessCell(before[field],field,'BRL')}}</span></div></div>
      <p class="case-summary">{{detail.summary}}</p>
      <ol class="journey-list" role="list"><li role="listitem" v-for="(item,index) in detail.results" :key="item.step"><span class="step-number">{{index+1}}</span><div><strong>{{labels[item.step]}}</strong><p>{{item.title}} · {{item.row_count}} 行完整结果</p></div><span class="done">已计算</span><button type="button" @click="viewResult(item.step)">查看结果</button></li><li role="listitem"><span class="step-number">5</span><div><strong>整理复盘材料</strong><p>已整理查询事实，保留 {{detail.report.fact_references.length}} 项数值依据。</p></div><span class="done">已整理</span><button type="button" @click="section='results';reportOpen=true">查看报告</button></li><li role="listitem"><span class="step-number pending">6</span><div><strong>核查原因，确认后交付</strong><p>统计变化已确认，经营原因和建议仍需人工核查。</p></div><span class="pending-label">待确认</span><button type="button" @click="section='confirmation'">查看核对项</button></li></ol>
    </section>
    <section v-else-if="section==='results'" class="case-panel" aria-label="示例分析结果">
      <div class="result-choices"><button v-for="item in detail.results" :key="item.step" type="button" :aria-pressed="step===item.step && !reportOpen" @click="step=item.step;reportOpen=false;showAll=false">{{labels[item.step]}}</button><button type="button" :aria-pressed="reportOpen" @click="reportOpen=true">事实报告</button></div>
      <template v-if="reportOpen"><h2>可直接浏览的示例事实报告</h2><p class="case-note">以下内容由查询事实整理，未加入模型推测的业务原因。</p><MarkdownReport :markdown="detail.report.markdown" /><details class="evidence-details"><summary>查看 {{detail.report.fact_references.length}} 项数值依据</summary><ul><li v-for="f in detail.report.fact_references" :key="f.id">{{f.label}}：{{f.display}} · {{f.source_title}}</li></ul></details></template>
      <template v-else-if="result"><h2>{{result.title}}</h2><p>{{result.analysis}}</p><div class="example-table" tabindex="0" aria-label="示例结果表，可左右滚动"><table><thead><tr><th v-for="col in result.columns" :key="col">{{businessLabel(col)}}</th></tr></thead><tbody><tr v-for="(row,index) in shownRows" :key="index"><td v-for="col in result.columns" :key="col" :title="String(row[col]??'')">{{businessCell(row[col],col,'BRL')}}</td></tr></tbody></table></div><div class="result-coverage"><span>展示 {{shownRows.length}} / {{result.row_count}} 行完整查询结果</span><button v-if="result.row_count>5" type="button" @click="showAll=!showAll">{{showAll?'收起到前五行':'显示全部结果'}}</button></div><details class="evidence-details"><summary>核对 SQL 与统计口径</summary><p v-for="contract in result.metric_contracts" :key="contract.label">{{contract.label}} v{{contract.version}}：{{contract.definition}}</p><pre><code>{{result.sql}}</code></pre></details></template>
    </section>
    <section v-else-if="section==='followups'" class="case-panel" aria-label="示例待核查事项"><h2>下一步核查什么</h2><p>这些是根据分析结果提出的待办示例。原因尚未验证，保持“待核查”，不会因浏览而变为已完成。</p><article v-for="todo in detail.followups" :key="todo.title" class="followup"><span class="status-tag">待核查</span><h3>{{todo.title}}</h3><p>{{todo.reason}}</p><button type="button" class="text-button" @click="viewResult(todo.step);reportOpen=false">查看相关结果：{{labels[todo.step]}}</button><details><summary>查看可继续追问的问题</summary><blockquote>{{todo.question}}</blockquote><button type="button" :disabled="busy" @click="emit('start',detail,todo.question)">创建分析并带入这个问题</button></details></article></section>
    <section v-else-if="section==='confirmation'" class="case-panel" aria-label="示例交付前确认"><h2>交付前，逐项核对</h2><p>先确认数据与口径，再检查业务判断。示例中的后两项保持待人工确认。</p><ul class="confirmation-list" role="list"><li role="listitem" v-for="check in detail.reconciliations" :key="check.title"><span class="done">已核对</span>{{check.title}}</li><li role="listitem"><span class="pending-label">待人工确认</span>经营原因有证据支撑；不把量价分解或相关性当作业务原因。</li><li role="listitem"><span class="pending-label">待人工确认</span>人工结论、下一步建议及交付对象已经核对。</li></ul><p class="case-note">这是交付核对示例，未记录真实业务审批。开始自己的分析后，可在报告中补充人工结论与下一步动作。</p><button type="button" :disabled="busy" @click="emit('start',detail)">开始我的复盘任务</button></section>
    <section v-else class="case-panel" aria-label="示例数据来源"><h2>每个结论都有可回看的来源</h2><dl class="source-grid"><dt>数据来源</dt><dd><a :href="detail.source.url" target="_blank" rel="noreferrer">{{detail.source.name}} ↗</a></dd><dt>许可</dt><dd>{{detail.source.license}}</dd><dt>本次观察期</dt><dd>{{detail.previous_month}} 与 {{detail.month}} · 下单时间</dd><dt>数据与单位</dt><dd>固定历史样本 · {{detail.source.currency}} · 商品金额不含运费</dd><dt>本次计算</dt><dd>{{new Date(detail.source.computed_at).toLocaleString('zh-CN')}}（不是业务数据更新时间）</dd></dl><p>{{detail.source.note}}</p><div class="source-links"><button v-for="item in detail.results" :key="item.step" type="button" @click="viewResult(item.step);reportOpen=false">{{item.title}} · {{item.row_count}} 行 ↗</button></div><p class="case-note">查询结果与明细口径可逐步核对；数据采集是否完整仍需上游证据。需要检查空值、重复标识和月份覆盖时，可回到经营概览使用数据可用性检查。</p></section>
  </template>
</section>
</template>

<style scoped>
.business-examples{color:#294c39;padding:4px 0 24px;--case-line:#ccdacf;--case-muted:#52685e}.examples-heading,.detail-heading{margin-bottom:24px}.eyebrow{display:block;color:#21654f;font-size:12px;letter-spacing:.06em;font-weight:600}.business-examples h1{font-size:clamp(23px,2.4vw,30px);line-height:1.5;margin:12px 0;font-weight:650;letter-spacing:-.025em}.business-examples p{font-size:14px;line-height:1.9;color:var(--case-muted);margin:10px 0}.examples-heading>p{max-width:700px}.example-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,255px),1fr));gap:18px}.example-cards article{display:flex;flex-direction:column;padding:22px;border:1px solid var(--case-line);border-radius:12px;background:#fff}.case-number{font-size:12px;color:#21654f;font-weight:600}.business-examples h2{font-size:18px;line-height:1.6;margin:12px 0}.example-cards h2{font-size:19px;min-height:3.2em}.example-cards p{flex:1}.example-cards dl{font-size:12px;line-height:1.8;margin:14px 0 20px}.example-cards dt{color:var(--case-muted);margin-top:8px}.example-cards dd{margin:0}.business-examples button{min-height:44px;border:1px solid #afc5b7;border-radius:7px;background:#fff;color:#21654f;padding:10px 14px;font:inherit;font-size:13px;cursor:pointer;line-height:1.5}.business-examples button:hover{background:#edf5ef}.business-examples button:disabled{opacity:.5;cursor:default}.example-cards button{display:flex;justify-content:space-between;width:100%;font-weight:600}.business-examples :is(button,summary,a,[tabindex]):focus-visible{outline:3px solid #5a9279;outline-offset:3px}.business-examples .case-note{font-size:12px;line-height:1.8}.back-link{margin-bottom:20px}.detail-heading h1{outline:none}.detail-heading h1:focus-visible{outline:3px solid #5a9279}.scope-line{font-size:13px!important}.example-actions{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0 10px}.business-examples .primary{background:#21654f;color:#fff;border-color:#21654f}.business-examples .primary:hover{background:#194f3e}.example-sections,.result-choices{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.example-sections button[aria-pressed=true],.result-choices button[aria-pressed=true]{background:#e2eee5;color:#1c593f;border-color:#75a389;font-weight:600}.case-panel{background:#fff;border:1px solid var(--case-line);border-radius:12px;padding:24px;min-width:0}.case-panel>h2:first-child{margin-top:0}.section-intro h2{margin-top:0}.status-tag,.done,.pending-label{font-size:12px;line-height:1.6}.status-tag{display:inline-block;border:1px solid #d9c394;padding:4px 8px;background:#fcf7ed;color:#765522;border-radius:5px}.done{color:#21654f}.pending-label{color:#795626}.case-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:24px 0}.case-metrics>div{padding:16px;border:1px solid #dce5de;border-radius:8px;background:#f7faf8;min-width:0}.case-metrics small,.case-metrics strong,.case-metrics span{display:block}.case-metrics small,.case-metrics span{font-size:12px;line-height:1.7;color:var(--case-muted)}.case-metrics strong{font-size:clamp(18px,2.2vw,25px);margin:7px 0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.case-summary{border-left:3px solid #77a28a;padding-left:14px}.journey-list{padding:0;list-style:none;margin:24px 0 0}.journey-list li{display:grid;grid-template-columns:30px minmax(0,1fr) auto auto;gap:14px;align-items:center;padding:16px 0;border-top:1px solid #e0e8e2}.step-number{width:28px;height:28px;background:#e6f0e9;color:#21654f;display:grid;place-items:center;border-radius:50%;font-size:12px}.step-number.pending{background:#fbf4e7;color:#795626}.journey-list strong{font-size:14px}.journey-list p{font-size:12px;margin:3px 0}.journey-list button{font-size:12px}.example-state{padding:24px;background:#fff;border:1px solid var(--case-line);border-radius:8px;margin:16px 0;font-size:14px;line-height:1.8}.failure{color:#9a3028}.example-table{overflow:auto;max-height:500px;border:1px solid #dce5de;border-radius:7px;margin-top:16px}.example-table table{border-spacing:0;width:100%;font-size:13px}.example-table th,.example-table td{white-space:nowrap;padding:12px;text-align:left;border-bottom:1px solid #e5ece7}.example-table th{background:#f2f7f3;position:sticky;top:0;z-index:2}.example-table th:first-child{left:0;z-index:3}.example-table td:first-child{position:sticky;left:0;background:#fff;z-index:1;box-shadow:1px 0 #dce5de}.result-coverage{display:flex;align-items:center;gap:12px;flex-wrap:wrap;justify-content:space-between;font-size:12px;color:var(--case-muted);margin:12px 0}.business-examples summary{cursor:pointer;min-height:44px;align-content:center;font-size:13px;line-height:1.7}.evidence-details{margin-top:18px;border-top:1px solid #e0e8e2;padding-top:10px}.evidence-details li{font-size:12px;line-height:1.9;overflow-wrap:anywhere}.business-examples pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f8f6;padding:14px;border-radius:6px;font-size:12px;line-height:1.8;max-height:350px;overflow:auto}.followup{border:1px solid #d4dfd7;border-radius:8px;padding:18px;margin-top:18px}.followup h3{font-size:16px;line-height:1.6}.business-examples blockquote{margin:12px 0;border-left:3px solid #bdcfc2;padding:8px 14px;font-size:13px;line-height:1.9;overflow-wrap:anywhere}.text-button{font-size:12px!important}.confirmation-list{list-style:none;padding:0}.confirmation-list li{padding:15px 0;border-bottom:1px solid #e0e8e2;font-size:14px;line-height:1.9;display:flex;align-items:start;gap:14px}.confirmation-list span{flex-shrink:0;margin-top:3px}.source-grid{display:grid;grid-template-columns:100px minmax(0,1fr);gap:14px;font-size:13px;line-height:1.8;margin:20px 0}.source-grid dt{color:var(--case-muted)}.source-grid dd{margin:0;overflow-wrap:anywhere}.source-grid a{color:#21654f}.source-links{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}
@media(max-width:620px){.example-cards{grid-template-columns:1fr}.example-cards article,.case-panel{padding:18px}.example-cards h2{min-height:0}.case-metrics{grid-template-columns:1fr;gap:8px}.case-metrics>div{display:grid;grid-template-columns:1fr auto;align-items:center;gap:4px}.case-metrics strong{font-size:22px;margin:0;grid-row:span 2}.case-metrics span{grid-column:1;grid-row:2}.journey-list li{grid-template-columns:28px minmax(0,1fr);gap:8px 12px}.journey-list .done,.journey-list .pending-label{grid-column:2}.journey-list button{grid-column:2;justify-self:start}.example-sections{gap:6px}.example-sections button{flex:1 1 100px;padding:9px}.example-actions{gap:8px}.example-actions button{width:100%}.confirmation-list li{flex-direction:column;gap:5px}.source-grid{grid-template-columns:1fr;gap:6px}.source-grid dd{margin-bottom:10px}.business-examples h1{font-size:24px}.business-examples p{font-size:14px}}
</style>

<style scoped>.example-cards h2{text-wrap:balance}</style>
